# Generic checks repeated per room (each room gets its own independent result)
def room_check(code, q, cost, flags, nl, en, it, tools="torch"):
    P(code, "ROOM", q=q, cost=cost, tools=tools, rooms="ANY", flags=flags, nl=nl, en=en, it=it)
